package app;

import static org.junit.jupiter.api.Assertions.assertEquals;

import dagger.Component;
import org.junit.jupiter.api.Test;

class GreeterTest {
    // DaggerGreeterTest_TestComponent is generated by testAnnotationProcessors
    @Component
    interface TestComponent {
        Main.Greeter greeter();
    }

    @Test
    void greets() {
        assertEquals("Hello, test", DaggerGreeterTest_TestComponent.create().greeter().greet("test"));
    }
}
